class D56V65PerceptionCancelled(RuntimeError):
    pass


D56V65_PERCEPTION_TLS = threading.local()


def _d56v65_perception_cancelled() -> bool:
    event = getattr(D56V65_PERCEPTION_TLS, "cancel_event", None)
    return bool(event is not None and event.is_set())

def _d56v65_raise_if_cancelled(where: str = "perception") -> None:
    if _d56v65_perception_cancelled():
        raise D56V65PerceptionCancelled(f"stale perception cancelled at {where}")
