def _d26v2_sample_mask(mask_u8: np.ndarray, points: np.ndarray) -> np.ndarray:
    pass
    pts = np.asarray(points, np.float32).reshape(-1, 2)
    h, w = mask_u8.shape[:2]
    xs = np.clip(np.rint(pts[:, 0]).astype(np.int32), 0, w - 1)
    ys = np.clip(np.rint(pts[:, 1]).astype(np.int32), 0, h - 1)
    return (mask_u8[ys, xs] > 0).astype(np.uint8)


def _d26v2_count_runs(values: np.ndarray, min_width: int = 3, min_gap: int = 2) -> int:
    pass
    v = np.asarray(values, np.uint8).reshape(-1)
    runs: List[Tuple[int, int]] = []
    start = None
    for i, x in enumerate(v):
        if x and start is None:
            start = i
        elif not x and start is not None:
            if i - start >= int(min_width):
                runs.append((start, i - 1))
            start = None
    if start is not None and len(v) - start >= int(min_width):
        runs.append((start, len(v) - 1))
    if len(runs) <= 1:
        return len(runs)
    merged = [runs[0]]
    for a, b in runs[1:]:
        pa, pb = merged[-1]
        if a - pb - 1 < int(min_gap):
            merged[-1] = (pa, b)
        else:
            merged.append((a, b))
    return len(merged)


def _d26v2_disk_mask_ratio(mask_u8: np.ndarray, center: np.ndarray, radius: int) -> float:
    c = np.asarray(center, np.float32).reshape(2)
    cx, cy = int(round(float(c[0]))), int(round(float(c[1])))
    r = max(2, int(radius))
    h, w = mask_u8.shape[:2]
    x0, x1 = max(0, cx-r), min(w, cx+r+1)
    y0, y1 = max(0, cy-r), min(h, cy+r+1)
    if x1 <= x0 or y1 <= y0:
        return 1.0
    yy, xx = np.ogrid[y0:y1, x0:x1]
    disk = (xx-cx)**2 + (yy-cy)**2 <= r*r
    denom = int(np.count_nonzero(disk))
    if denom <= 0:
        return 1.0
    return float(np.count_nonzero((mask_u8[y0:y1, x0:x1] > 0) & disk)) / float(denom)



def _d26v2_leg_opening_guard(obs: Optional[BottomObservation], args) -> Dict[str, Any]:
    pass
    out: Dict[str, Any] = {
        "good": False,
        "tier": "UNCERTAIN",
        "explicit_overlap": False,
        "uncertain": True,
        "reason": "unavailable",
        "checks": {},
        "metrics": {},
    }
    if obs is None or obs.mask is None or obs.pose is None:
        out["reason"] = "pose_or_mask_missing"
        return out
    kp = getattr(obs.pose, "keypoints_px", {}) or {}
    required = (
        "waist_img_left", "waist_center", "waist_img_right",
        "img_left_hem_outer", "img_left_hem_inner",
        "img_right_hem_inner", "img_right_hem_outer",
    )
    if any(name not in kp for name in required):
        out["reason"] = "required_pose_points_missing"
        return out

    def pt(name: str) -> np.ndarray:
        return np.asarray(kp[name], np.float32).reshape(2)

    wl, wc, wr = pt("waist_img_left"), pt("waist_center"), pt("waist_img_right")
    lho, lhi = pt("img_left_hem_outer"), pt("img_left_hem_inner")
    rhi, rho = pt("img_right_hem_inner"), pt("img_right_hem_outer")
    lh = 0.5 * (lho + lhi)
    rh = 0.5 * (rhi + rho)
    hem_center = 0.5 * (lh + rh)
    body = hem_center - wc
    body_len = float(np.linalg.norm(body))
    if body_len < 20.0:
        out["reason"] = "body_axis_too_short"
        return out
    body_u = body / body_len
    lat_u = np.asarray([-body_u[1], body_u[0]], np.float32)
    if float(np.dot(wr - wl, lat_u)) < 0.0:
        lat_u = -lat_u

    waist_span = max(1.0, float(abs(np.dot(wr - wl, lat_u))))
    left_hem_width = float(abs(np.dot(lhi - lho, lat_u)))
    right_hem_width = float(abs(np.dot(rho - rhi, lat_u)))
    inner_gap = float(abs(np.dot(rhi - lhi, lat_u)))
    inner_mid = 0.5 * (lhi + rhi)

    mask = ((np.asarray(obs.mask.mask_u8, np.uint8) > 0).astype(np.uint8) * 255)
    erode_px = max(0, int(getattr(args, "d26v2_leg_gap_erode_px", 3)))
    topo = mask
    if erode_px > 0:
        k = erode_px * 2 + 1
        candidate = cv2.erode(mask, cv2.getStructuringElement(cv2.MORPH_ELLIPSE, (k, k)), iterations=1)
        if cv2.countNonZero(candidate) >= 0.65 * max(1, cv2.countNonZero(mask)):
            topo = candidate

    disk_radius = int(np.clip(
        waist_span * float(getattr(args, "d26v2_inner_gap_disk_ratio", 0.045)),
        float(getattr(args, "d26v2_inner_gap_disk_min_px", 6.0)),
        float(getattr(args, "d26v2_inner_gap_disk_max_px", 22.0)),
    ))
    inner_mid_mask_ratio = _d26v2_disk_mask_ratio(topo, inner_mid, disk_radius)

    ts = np.linspace(0.22, 0.78, 29, dtype=np.float32)
    bridge_pts = lhi.reshape(1, 2) * (1.0 - ts[:, None]) + rhi.reshape(1, 2) * ts[:, None]
    bridge_values = _d26v2_sample_mask(topo, bridge_pts)
    bridge_background_ratio = 1.0 - float(np.mean(bridge_values))

    scan_count = max(8, int(getattr(args, "d26v2_leg_scan_count", 18)))
    lateral_samples = max(81, int(getattr(args, "d26v2_leg_scan_lateral_samples", 161)))
    scan_start = float(getattr(args, "d26v2_leg_scan_start_ratio", 0.58))
    scan_end = float(getattr(args, "d26v2_leg_scan_end_ratio", 1.06))
    lat_half = max(waist_span * float(getattr(args, "d26v2_leg_scan_half_width_ratio", 0.78)), 36.0)
    ss = np.linspace(-lat_half, lat_half, lateral_samples, dtype=np.float32)
    two_run_rows = 0
    max_runs = 0
    row_runs: List[int] = []
    for t in np.linspace(scan_start, scan_end, scan_count, dtype=np.float32):
        center = wc + body_u * (body_len * float(t))
        row_pts = center.reshape(1, 2) + ss[:, None] * lat_u.reshape(1, 2)
        vals = _d26v2_sample_mask(topo, row_pts)
        runs = _d26v2_count_runs(
            vals,
            min_width=max(2, int(getattr(args, "d26v2_leg_scan_min_run_samples", 4))),
            min_gap=max(2, int(getattr(args, "d26v2_leg_scan_min_gap_samples", 3))),
        )
        row_runs.append(int(runs))
        max_runs = max(max_runs, int(runs))
        if runs >= 2:
            two_run_rows += 1
    two_run_ratio = float(two_run_rows) / float(max(1, scan_count))

    hem_width_min_ratio = min(left_hem_width, right_hem_width) / waist_span
    inner_gap_ratio = inner_gap / waist_span
    distinct_hems = bool(
        hem_width_min_ratio >= float(getattr(args, "d26v2_min_hem_width_ratio", 0.075))
        and inner_gap_ratio >= float(getattr(args, "d26v2_min_inner_gap_ratio", 0.045))
    )
    midpoint_clear = bool(
        inner_mid_mask_ratio <= float(getattr(args, "d26v2_inner_mid_mask_ratio_max", 0.46))
        and bridge_background_ratio >= float(getattr(args, "d26v2_bridge_background_ratio_min", 0.30))
    )
    two_lobes = bool(
        max_runs >= 2
        and two_run_ratio >= float(getattr(args, "d26v2_two_lobe_row_ratio_min", 0.12))
    )

    explicit_overlap = bool(
        not distinct_hems
        and not midpoint_clear
        and not two_lobes
        and inner_gap_ratio <= float(getattr(args, "d27_explicit_overlap_inner_gap_ratio_max", 0.030))
        and bridge_background_ratio <= float(getattr(args, "d27_explicit_overlap_bridge_background_max", 0.12))
        and inner_mid_mask_ratio >= float(getattr(args, "d27_explicit_overlap_inner_mask_min", 0.72))
        and two_run_ratio <= float(getattr(args, "d27_explicit_overlap_two_run_ratio_max", 0.03))
    )
    strict = bool(distinct_hems and midpoint_clear and two_lobes)
    good_enough = bool(
        not explicit_overlap
        and not strict
        and (
            (distinct_hems and midpoint_clear)
            or (distinct_hems and two_lobes)
            or (
                midpoint_clear
                and inner_gap_ratio >= float(getattr(args, "d27_good_enough_inner_gap_ratio_min", 0.080))
                and hem_width_min_ratio >= float(getattr(args, "d27_good_enough_hem_width_ratio_min", 0.060))
            )
        )
    )
    if strict:
        tier, reason = "STRICT", "STRICT_LEG_OPEN"
    elif good_enough:
        tier, reason = "GOOD_ENOUGH", "CENTER_BACKGROUND_AND_HEM_SEPARATION"
    elif explicit_overlap:
        tier, reason = "EXPLICIT_OVERLAP", "EXPLICIT_LEG_OVERLAP"
    else:
        tier, reason = "UNCERTAIN", "LEG_OPENING_UNCERTAIN_REJUDGE"
    good = tier in {"STRICT", "GOOD_ENOUGH"}

    checks = {
        "distinct_hem_segments": distinct_hems,
        "real_background_between_inner_hems": midpoint_clear,
        "two_leg_mask_lobes": two_lobes,
        "strict": strict,
        "good_enough": good_enough,
        "explicit_overlap": explicit_overlap,
    }
    metrics = {
        "waist_span_px": waist_span,
        "left_hem_width_px": left_hem_width,
        "right_hem_width_px": right_hem_width,
        "min_hem_width_waist_ratio": hem_width_min_ratio,
        "inner_hem_gap_px": inner_gap,
        "inner_hem_gap_waist_ratio": inner_gap_ratio,
        "inner_mid_mask_ratio": inner_mid_mask_ratio,
        "bridge_background_ratio": bridge_background_ratio,
        "two_run_row_ratio": two_run_ratio,
        "two_run_rows": int(two_run_rows),
        "scan_rows": int(scan_count),
        "max_foreground_runs": int(max_runs),
        "row_runs": row_runs,
        "topology_erode_px": int(erode_px),
    }
    out.update({
        "good": good,
        "tier": tier,
        "explicit_overlap": explicit_overlap,
        "uncertain": tier == "UNCERTAIN",
        "reason": reason,
        "checks": checks,
        "metrics": metrics,
    })
    return out


def _d26v6_residual_wrinkle_guard(heat, obs, H, args) -> Dict[str, Any]:
    pass
    out: Dict[str, Any] = {
        "good": False, "reason": "unavailable", "checks": {}, "metrics": {},
        "blockers": [], "ignored_pattern_count": 0,
    }
    if heat is None or obs is None or getattr(obs, "mask", None) is None:
        out["reason"] = "heat_or_mask_unavailable"
        return out

    mask_area = max(1.0, float(obs.mask.area_px))
    effective_area = max(1.0, float(cv2.countNonZero(heat.inner_mask)))
    action_candidates = list(getattr(heat, "candidates", []) or [])
    all_candidates = list(getattr(heat, "d21v4_all_candidates", []) or action_candidates)

    mild_action_count = 0
    hard_action_count = 0
    supported_action_count = 0
    ignored_pattern_count = 0
    action_area = 0.0
    action_details: List[Dict[str, Any]] = []
    mild_len_max = float(getattr(args, "d27_practical_mild_length_mm", 48.0))
    mild_area_max = float(getattr(args, "d27_practical_mild_area_ratio", 0.0045))
    mild_severity_max = float(getattr(args, "d27_practical_mild_severity", 0.50))

    for original in action_candidates:
        c = dict(original)
        if bool(c.get("d27_terminal", False)):
            continue
        photo = _d27_candidate_photo_report(c, args)
        if not bool(photo.get("supported", False)):
            ignored_pattern_count += 1
            action_details.append({"ignored": "NO_PHOTO_SUPPORT", "photo": photo})
            continue
        area = float(c.get("area_px", 0.0))
        area_ratio = area / mask_area
        length = float(c.get("major_length_mm", 0.0))
        if length <= 0.0:
            try:
                length = float(_d16_candidate_length_mm(c, H))
            except Exception:
                length = 0.0
        severity = float(c.get("d21_severity", c.get("severity", c.get("severity_score", 0.0))))
        tier = int(c.get("d20_priority_tier", c.get("d20_tier", c.get("tier", 0))))
        mild = bool(
            tier <= 1 and length <= mild_len_max
            and area_ratio <= mild_area_max and severity <= mild_severity_max
        )
        supported_action_count += 1
        action_area += area
        if mild:
            mild_action_count += 1
        else:
            hard_action_count += 1
        action_details.append({
            "tier": tier, "length_mm": length, "area_ratio": area_ratio,
            "severity": severity, "mild": mild, "photo": photo,
        })

    robust_threshold = d25v2.robust_heat_threshold(heat, args)
    try:
        waist_ref = d25v2._d24v2_waist_reference(obs, heat, H, robust_threshold, args)
    except Exception:
        waist_ref = None

    significant: List[Dict[str, Any]] = []
    residual_area = 0.0
    max_residual_ratio = 0.0
    for original in all_candidates:
        cand = dict(original)
        if bool(cand.get("d27_terminal", False)):
            continue
        photo = _d27_candidate_photo_report(cand, args)
        if not bool(photo.get("supported", False)):
            continue
        try:
            seam = d25v2.seam_veto_report(cand, heat, obs, H, args)
            if bool(seam.get("matched", False)):
                continue
            support = float(d25v2.candidate_robust_support(cand, heat, float(robust_threshold["threshold"])))
            if support < max(
                float(getattr(args, "d24_candidate_min_robust_support", 0.10)),
                float(getattr(args, "d27_practical_min_robust_support", 0.16)),
            ):
                continue
            metrics = d25v2._d24v2_candidate_metrics(cand, heat, obs, waist_ref)
            gather = d25v2._d24v5_waist_gather_report(cand, heat, obs, H, metrics, args)
            if bool(gather.get("matched", False)):
                continue
        except Exception:
            continue

        area = float(cand.get("area_px", 0.0))
        area_ratio = float(metrics.get("area_ratio", area / mask_area))
        length = float(metrics.get("length_mm", cand.get("major_length_mm", 0.0)))
        width = float(cand.get("minor_length_mm", 0.0))
        linearity = max(1.0, float(cand.get("linearity", 1.0)))
        if width <= 0.0 and length > 0.0:
            width = length / linearity
        broad = bool(length >= 42.0 and width >= 12.0 and area_ratio >= 0.0035)
        long_linear = bool(length >= 60.0 and linearity >= 1.8 and area_ratio >= 0.0020)
        dominant = bool(area_ratio >= 0.012 and length >= 35.0)
        if not (broad or long_linear or dominant):
            continue
        item = {
            "area_px": area, "area_ratio": area_ratio, "length_mm": length,
            "width_mm": width, "linearity": linearity, "broad": broad,
            "long_linear": long_linear, "dominant": dominant, "photo": photo,
        }
        significant.append(item)
        residual_area += area
        max_residual_ratio = max(max_residual_ratio, area_ratio)

    action_ratio = action_area / effective_area
    residual_total_ratio = residual_area / mask_area
    checks = {
        "no_hard_action_candidate": hard_action_count == 0,
        "mild_action_candidate_count": mild_action_count <= int(getattr(args, "d27_practical_max_mild_candidates", 1)),
        "significant_residual_count": len(significant) <= int(getattr(args, "d27_practical_max_significant_residuals", 0)),
        "actionable_ratio": action_ratio <= float(getattr(args, "d27_practical_actionable_ratio_max", 0.035)),
        "residual_total_area_ratio": residual_total_ratio <= float(getattr(args, "d27_practical_residual_total_ratio_max", 0.025)),
        "residual_max_blob_ratio": max_residual_ratio <= float(getattr(args, "d27_practical_residual_max_blob_ratio", 0.015)),
    }
    good = bool(all(checks.values()))
    out.update({
        "good": good,
        "reason": "OK" if good else "PHOTO_SUPPORTED_WRINKLES_REMAIN",
        "checks": checks,
        "metrics": {
            "action_candidate_count": len(action_candidates),
            "photo_supported_action_count": supported_action_count,
            "hard_action_candidate_count": hard_action_count,
            "mild_action_candidate_count": mild_action_count,
            "significant_residual_count": len(significant),
            "actionable_ratio": action_ratio,
            "residual_total_area_ratio": residual_total_ratio,
            "residual_max_blob_ratio": max_residual_ratio,
            "ignored_pattern_count": ignored_pattern_count,
        },
        "ignored_pattern_count": ignored_pattern_count,
        "action_details": action_details,
        "blockers": significant,
    })
    return out

def _d26v7_candidate_center_board(cand: Dict[str, Any], H: Optional[np.ndarray]) -> Optional[np.ndarray]:
    pass
    center_board = cand.get("center_board")
    if center_board is not None:
        try:
            return np.asarray(center_board, np.float32).reshape(2)
        except Exception:
            pass
    center_px = cand.get("center_px")
    if center_px is None or H is None:
        return None
    try:
        p = np.asarray(center_px, np.float32).reshape(2)
        return np.asarray(pixel_to_board(H, float(p[0]), float(p[1])), np.float32)
    except Exception:
        return None


def _d26v7_persistent_action_report(samples: Sequence[Dict[str, Any]],
                                     H: Optional[np.ndarray], args) -> Dict[str, Any]:
    pass
    items: List[Dict[str, Any]] = []
    terminal_ignored = 0
    for frame_index, sample in enumerate(samples):
        obs = sample.get("obs")
        heat = sample.get("heat")
        if obs is None or getattr(obs, "mask", None) is None or heat is None:
            continue
        mask_area = max(1.0, float(obs.mask.area_px))
        for original in list(getattr(heat, "candidates", []) or []):
            cand = dict(original)
            sig = _d27_candidate_signature(cand, obs, H)
            tid = int(sig.get("track_id", -1))
            with D21_MEMORY_LOCK:
                tr = D21_WRINKLE_TRACKS.get(tid)
                terminal = _d27_track_terminal(tr)
                terminal_state = str((tr or {}).get("d27_state", "NEW"))
            if terminal and bool(getattr(args, "d27_track_terminal_lock", True)):
                terminal_ignored += 1
                continue
            photo = _d27_candidate_photo_report(cand, args)
            area = float(cand.get("area_px", 0.0))
            items.append({
                "frame": int(frame_index),
                "signature": sig,
                "center": np.asarray(sig["center"], np.float32),
                "track_id": tid,
                "terminal_state": terminal_state,
                "tier": int(cand.get("d20_priority_tier", cand.get("d20_tier", cand.get("tier", 0)))),
                "severity": float(cand.get("d21_severity", cand.get("severity", cand.get("severity_score", 0.0)))),
                "length_mm": float(sig.get("length_mm", 0.0)),
                "area_ratio": float(area / mask_area),
                "linearity": float(cand.get("linearity", 1.0)),
                "shape_class": str(sig.get("shape_class", "IRREGULAR")),
                "photo": photo,
            })

    clusters: List[Dict[str, Any]] = []
    items.sort(key=lambda x: (
        bool(x["photo"].get("supported", False)), x["tier"], x["severity"],
        x["area_ratio"], x["length_mm"]
    ), reverse=True)
    for item in items:
        chosen = None
        best_cost = float("inf")
        for cluster in clusters:
            if item["frame"] in cluster["frames"]:
                continue
            ok, cost = _d27_signature_match(item["signature"], cluster["signature"], args)
            if ok and cost < best_cost:
                chosen = cluster
                best_cost = cost
        if chosen is None:
            clusters.append({
                "signature": dict(item["signature"]),
                "frames": {item["frame"]},
                "items": [item],
            })
        else:
            chosen["items"].append(item)
            chosen["frames"].add(item["frame"])
            centers = np.stack([x["center"] for x in chosen["items"]], axis=0)
            chosen["signature"]["center"] = np.mean(centers, axis=0).astype(np.float32)
            for key in ("pose_s", "pose_d", "angle_deg", "length_mm"):
                chosen["signature"][key] = float(np.median([
                    float(x["signature"].get(key, 0.0)) for x in chosen["items"]
                ]))

    required = max(2, int(getattr(args, "d26v7_persistent_required_frames", 2)))
    min_tier = int(getattr(args, "d26v7_persistent_hard_tier", 2))
    min_severity = float(getattr(args, "d26v7_persistent_hard_severity", 0.50))
    min_length = float(getattr(args, "d26v7_persistent_hard_length_mm", 55.0))
    min_area_ratio = float(getattr(args, "d26v7_persistent_hard_area_ratio", 0.0025))
    require_photo = bool(getattr(args, "d27_require_photo_for_finish_block", True))
    persistent: List[Dict[str, Any]] = []
    hard: List[Dict[str, Any]] = []
    texture_only: List[Dict[str, Any]] = []
    for cluster in clusters:
        vals = cluster["items"]
        support = len(cluster["frames"])
        photo_votes = sum(bool(x["photo"].get("supported", False)) for x in vals)
        explicit_fold_votes = sum(x["photo"].get("is_fold") is True for x in vals)
        report = {
            "support_frames": int(support),
            "center_board": [
                float(cluster["signature"]["center"][0]),
                float(cluster["signature"]["center"][1]),
            ],
            "pose_s": float(cluster["signature"].get("pose_s", 0.0)),
            "pose_d": float(cluster["signature"].get("pose_d", 0.0)),
            "median_angle_deg": float(np.median([x["signature"].get("angle_deg", 0.0) for x in vals])),
            "shape_class": str(cluster["signature"].get("shape_class", "IRREGULAR")),
            "track_ids": sorted({int(x.get("track_id", -1)) for x in vals if int(x.get("track_id", -1)) >= 0}),
            "median_tier": float(np.median([x["tier"] for x in vals])),
            "median_severity": float(np.median([x["severity"] for x in vals])),
            "median_length_mm": float(np.median([x["length_mm"] for x in vals])),
            "median_area_ratio": float(np.median([x["area_ratio"] for x in vals])),
            "median_linearity": float(np.median([x["linearity"] for x in vals])),
            "photo_supported_frames": int(photo_votes),
            "explicit_fold_frames": int(explicit_fold_votes),
            "photo_reports": [x["photo"] for x in vals],
        }
        geometry_actionable = bool(
            report["median_tier"] >= min_tier
            or report["median_severity"] >= min_severity
            or (
                report["median_length_mm"] >= min_length
                and report["median_area_ratio"] >= min_area_ratio
            )
        )
        photo_actionable = bool(
            photo_votes >= required
            or explicit_fold_votes >= 1
        )
        report["texture_only"] = bool(
            support >= required and geometry_actionable and not photo_actionable
        )
        report["hard"] = bool(
            support >= required
            and geometry_actionable
            and (photo_actionable or not require_photo)
        )
        if support >= required:
            persistent.append(report)
        if report["texture_only"]:
            texture_only.append(report)
        if report["hard"]:
            hard.append(report)

    return {
        "good": len(hard) == 0,
        "reason": "OK" if not hard else "PERSISTENT_PHOTO_SUPPORTED_WRINKLE",
        "candidate_count": len(items),
        "cluster_count": len(clusters),
        "persistent_count": len(persistent),
        "hard_persistent_count": len(hard),
        "texture_only_count": len(texture_only),
        "terminal_ignored_count": int(terminal_ignored),
        "persistent": persistent,
        "hard": hard,
        "texture_only": texture_only,
        "limits": {
            "required_frames": required,
            "match_radius_mm": float(getattr(args, "d26v7_persistent_match_radius_mm", 48.0)),
            "hard_tier": min_tier,
            "hard_severity": min_severity,
            "hard_length_mm": min_length,
            "hard_area_ratio": min_area_ratio,
            "require_photo": require_photo,
            "angle_tol_deg": float(getattr(args, "d27_persistent_angle_tol_deg", 28.0)),
            "length_rel_tol": float(getattr(args, "d27_persistent_length_rel_tol", 0.40)),
        },
    }


def _d26v7_binary_vote_report(samples: Sequence[Dict[str, Any]], args) -> Dict[str, Any]:
    pass
    binaries: List[np.ndarray] = []
    inners: List[np.ndarray] = []
    for sample in samples:
        heat = sample.get("heat")
        if heat is None:
            continue
        binary = getattr(heat, "d21v4_residual_binary", None)
        if binary is None:
            binary = getattr(heat, "binary", None)
        inner = getattr(heat, "inner_mask", None)
        if binary is None or inner is None:
            continue
        binaries.append((np.asarray(binary, np.uint8) > 0).astype(np.uint8))
        inners.append((np.asarray(inner, np.uint8) > 0).astype(np.uint8))
    if len(binaries) < 2:
        return {"available": False, "persistent_ratio": 1.0, "persistent_blob_count": 0}
    shape = binaries[0].shape
    binaries = [cv2.resize(x, (shape[1], shape[0]), interpolation=cv2.INTER_NEAREST) if x.shape != shape else x for x in binaries]
    inners = [cv2.resize(x, (shape[1], shape[0]), interpolation=cv2.INTER_NEAREST) if x.shape != shape else x for x in inners]
    required = min(len(binaries), max(2, int(getattr(args, "d26v7_consensus_required", 2))))
    active_vote = np.sum(np.stack(binaries, axis=0), axis=0) >= required
    inner_vote = np.sum(np.stack(inners, axis=0), axis=0) >= required
    persistent = (active_vote & inner_vote).astype(np.uint8)
    inner_area = max(1, int(np.count_nonzero(inner_vote)))
    ratio = float(np.count_nonzero(persistent)) / float(inner_area)
    n, _labels, stats, _centers = cv2.connectedComponentsWithStats(persistent, 8)
    min_area = max(80, int(round(inner_area * float(getattr(args, "d26v7_persistent_blob_min_area_ratio", 0.0015)))))
    blob_count = 0
    max_blob_ratio = 0.0
    for idx in range(1, int(n)):
        area = int(stats[idx, cv2.CC_STAT_AREA])
        if area < min_area:
            continue
        blob_count += 1
        max_blob_ratio = max(max_blob_ratio, float(area) / float(inner_area))
    return {
        "available": True,
        "frame_count": len(binaries),
        "required": required,
        "persistent_ratio": ratio,
        "persistent_blob_count": blob_count,
        "persistent_max_blob_ratio": max_blob_ratio,
        "min_blob_area_px": min_area,
    }



def _d26v7_consensus_report(samples: Sequence[Dict[str, Any]],
                             H: Optional[np.ndarray], args) -> Dict[str, Any]:
    pass
    if not samples:
        return {"good": False, "summary": "REMAIN D27V3_V4 no consensus samples", "remaining": ["consensus:no_samples"]}
    reports = [s["report"] for s in samples]
    frame_count = len(reports)
    required = min(frame_count, max(2, int(getattr(args, "d26v7_consensus_required", 2))))

    quality_votes = sum(bool(r.get("quality", {}).get("good", False)) for r in reports)
    base_shape_votes = sum(bool(r.get("shape", {}).get("base_shape_good", r.get("shape", {}).get("shape_good", False))) for r in reports)
    leg_tiers = [str(r.get("leg_opening", {}).get("tier", "UNCERTAIN")) for r in reports]
    strict_leg_votes = sum(t == "STRICT" for t in leg_tiers)
    good_enough_leg_votes = sum(t == "GOOD_ENOUGH" for t in leg_tiers)
    leg_votes = strict_leg_votes + good_enough_leg_votes
    explicit_overlap_votes = sum(t == "EXPLICIT_OVERLAP" for t in leg_tiers)
    uncertain_leg_votes = sum(t == "UNCERTAIN" for t in leg_tiers)
    macro_votes = sum(bool(r.get("wrinkle", {}).get("good", False)) for r in reports)

    persistent = _d26v7_persistent_action_report(samples, H, args)
    binary_vote = _d26v7_binary_vote_report(samples, args)

    transforms: Dict[str, int] = {}
    mask_areas: List[float] = []
    frame_rows: List[Dict[str, Any]] = []
    for i, sample in enumerate(samples):
        obs = sample.get("obs")
        report = sample.get("report", {})
        pose = None if obs is None else getattr(obs, "pose", None)
        key = "none"
        if pose is not None:
            key = f"{float(getattr(pose, 'tta_angle_deg', 0.0)):+.1f}/{getattr(pose, 'tta_flip_mode', 'none')}"
        transforms[key] = transforms.get(key, 0) + 1
        if obs is not None and getattr(obs, "mask", None) is not None:
            mask_areas.append(float(obs.mask.area_px))
        frame_rows.append({
            "frame": i + 1,
            "quality": bool(report.get("quality", {}).get("good", False)),
            "base_shape": bool(report.get("shape", {}).get("base_shape_good", report.get("shape", {}).get("shape_good", False))),
            "leg_tier": str(report.get("leg_opening", {}).get("tier", "UNCERTAIN")),
            "leg_open": bool(report.get("leg_opening", {}).get("good", False)),
            "macro_clear": bool(report.get("wrinkle", {}).get("good", False)),
            "single_residual_clear": bool(report.get("residual_wrinkle", {}).get("good", False)),
            "shape_score": float(report.get("shape", {}).get("shape_score", 0.0)),
            "tta": key,
            "summary": str(report.get("summary", "")),
        })

    dominant_transform = max(transforms.items(), key=lambda kv: kv[1]) if transforms else ("none", 0)
    mask_cv = 0.0
    if len(mask_areas) >= 2 and float(np.mean(mask_areas)) > 1e-6:
        mask_cv = float(np.std(mask_areas) / np.mean(mask_areas))

    aggregate_leg_tier = (
        "EXPLICIT_OVERLAP" if explicit_overlap_votes >= required
        else "STRICT" if strict_leg_votes == frame_count
        else "GOOD_ENOUGH" if leg_votes >= required
        else "UNCERTAIN"
    )
    checks = {
        "observation_consensus": quality_votes >= required,
        "shape_consensus": base_shape_votes >= required,
        "leg_open_consensus": leg_votes >= required,
        "no_explicit_overlap_consensus": explicit_overlap_votes < required,
        "macro_fold_consensus": macro_votes >= required,
        "no_persistent_actionable_wrinkle": bool(persistent.get("good", False)),
    }
    good = bool(all(checks.values()))

    frame_scores: List[float] = []
    dominant_key = dominant_transform[0]
    for row in frame_rows:
        score = (
            2.0 * float(row["quality"]) + 2.0 * float(row["base_shape"])
            + 2.0 * float(row["leg_open"]) + 2.0 * float(row["macro_clear"])
            + 0.8 * float(row["single_residual_clear"]) + float(row["shape_score"])
            + 0.35 * float(row["tta"] == dominant_key)
        )
        frame_scores.append(score)
    representative_index = int(np.argmax(frame_scores))
    representative = copy.deepcopy(reports[representative_index])
    representative_shape = copy.deepcopy(representative.get("shape", {}))
    representative_shape["shape_good"] = bool(checks["shape_consensus"] and aggregate_leg_tier != "EXPLICIT_OVERLAP")
    representative_shape["consensus_shape_votes"] = int(base_shape_votes)
    representative_shape["consensus_leg_votes"] = int(leg_votes)
    representative_shape["leg_open_tier"] = aggregate_leg_tier
    representative["shape"] = representative_shape
    rep_leg = copy.deepcopy(representative.get("leg_opening", {}))
    rep_leg.update({
        "tier": aggregate_leg_tier,
        "good": aggregate_leg_tier in {"STRICT", "GOOD_ENOUGH"},
        "explicit_overlap": aggregate_leg_tier == "EXPLICIT_OVERLAP",
        "uncertain": aggregate_leg_tier == "UNCERTAIN",
        "consensus_votes": {
            "strict": strict_leg_votes, "good_enough": good_enough_leg_votes,
            "uncertain": uncertain_leg_votes, "explicit_overlap": explicit_overlap_votes,
        },
    })
    representative["leg_opening"] = rep_leg

    remaining = [f"consensus:{name}" for name, passed in checks.items() if not passed]
    strict = bool(
        good and quality_votes == frame_count and base_shape_votes == frame_count
        and strict_leg_votes == frame_count and macro_votes == frame_count
    )
    finish_tier = "STRICT" if strict else ("GOOD_ENOUGH" if good else "REMAIN")
    summary = (
        f"{'FINISH' if good else 'REMAIN'} D27V3_V4 {finish_tier} "
        f"obs={quality_votes}/{frame_count} shape={base_shape_votes}/{frame_count} "
        f"legs={aggregate_leg_tier}({leg_votes}/{frame_count}) macro={macro_votes}/{frame_count} "
        f"persistentReal={int(persistent.get('hard_persistent_count', 0))} "
        f"textureOnly={int(persistent.get('texture_only_count', 0))}"
    )
    representative.update({
        "good": good,
        "heat_good": bool(checks["macro_fold_consensus"] and checks["no_persistent_actionable_wrinkle"]),
        "checks": checks,
        "remaining": remaining,
        "summary": summary,
        "consensus": {
            "enabled": True, "frame_count": frame_count, "required": required,
            "quality_votes": quality_votes, "shape_votes": base_shape_votes,
            "leg_open_votes": leg_votes, "strict_leg_votes": strict_leg_votes,
            "good_enough_leg_votes": good_enough_leg_votes,
            "uncertain_leg_votes": uncertain_leg_votes,
            "explicit_overlap_votes": explicit_overlap_votes,
            "aggregate_leg_tier": aggregate_leg_tier,
            "macro_clear_votes": macro_votes,
            "dominant_tta": dominant_transform[0], "dominant_tta_votes": dominant_transform[1],
            "mask_area_cv": mask_cv, "representative_index": representative_index,
            "frames": frame_rows, "persistent_action": persistent,
            "binary_vote": binary_vote, "finish_tier": finish_tier,
            "texture_only_count": int(persistent.get("texture_only_count", 0)),
            "terminal_ignored_count": int(persistent.get("terminal_ignored_count", 0)),
        },
    })
    representative["residual_wrinkle"] = {
        "good": bool(persistent.get("good", False)),
        "reason": str(persistent.get("reason", "")),
        "metrics": {
            "hard_action_candidate_count": int(persistent.get("hard_persistent_count", 0)),
            "significant_residual_count": int(persistent.get("hard_persistent_count", 0)),
            "residual_total_area_ratio": float(binary_vote.get("persistent_ratio", 0.0)),
        },
        "persistent": persistent, "binary_vote": binary_vote,
    }
    return representative

def _d26v7_should_run_consensus(report: Dict[str, Any], args) -> bool:
    pass
    if not bool(getattr(args, "d26v7_consensus_finish", True)):
        return False
    if bool(report.get("good", False)):
        return True
    quality_good = bool(report.get("quality", {}).get("good", False))
    shape_score = float(report.get("shape", {}).get("shape_score", 0.0))
    fold_count = int(report.get("wrinkle", {}).get("fold_count", 0))
    outer_count = int(report.get("wrinkle", {}).get("outer_macro_fold_count", 0))
    return bool(
        quality_good
        and shape_score >= float(getattr(args, "d26v7_consensus_near_shape_score", 0.42))
        and fold_count <= int(getattr(args, "d26v7_consensus_near_macro_fold_max", 0))
        and outer_count <= int(getattr(args, "d26v7_consensus_near_outer_fold_max", 0))
    )



def _d27v3v2_effective_leg_report(raw_leg: Dict[str, Any],
                                      shape: Dict[str, Any],
                                      quality: Dict[str, Any],
                                      args) -> Dict[str, Any]:
    pass
    report = copy.deepcopy(raw_leg or {})
    raw_tier = str(report.get("tier", "UNCERTAIN"))
    report["raw_tier"] = raw_tier
    report["fallback_from_uncertain"] = False

    if raw_tier != "UNCERTAIN":
        return report
    if not bool(getattr(args, "d27_uncertain_leg_shape_fallback", True)):
        return report
    if bool(report.get("explicit_overlap", False)):
        return report

    quality_good = bool(quality.get("good", False))
    base_shape_good = bool(shape.get("shape_good", False))
    shape_score = float(shape.get("shape_score", 0.0))
    pose_structure_good = bool(shape.get("pose_structure", {}).get("good", False))
    hard_structure_good = bool(shape.get("hard_structure_good", False))
    geometry_score = float(shape.get("geometry_support", {}).get("score", 0.0))
    macro_outer_fold = bool(shape.get("macro_outer_fold", False))

    structure_support = bool(
        pose_structure_good
        or hard_structure_good
        or geometry_score >= float(getattr(args, "d27_uncertain_leg_geometry_score_min", 0.45))
    )
    fallback_good = bool(
        quality_good
        and base_shape_good
        and shape_score >= float(getattr(args, "d27_uncertain_leg_shape_score_min", 0.72))
        and structure_support
        and not macro_outer_fold
    )
    report["fallback_checks"] = {
        "quality_good": quality_good,
        "base_shape_good": base_shape_good,
        "shape_score": shape_score,
        "shape_score_min": float(getattr(args, "d27_uncertain_leg_shape_score_min", 0.72)),
        "pose_structure_good": pose_structure_good,
        "hard_structure_good": hard_structure_good,
        "geometry_score": geometry_score,
        "geometry_score_min": float(getattr(args, "d27_uncertain_leg_geometry_score_min", 0.45)),
        "structure_support": structure_support,
        "macro_outer_fold": macro_outer_fold,
    }
    if fallback_good:
        report.update({
            "good": True,
            "tier": "GOOD_ENOUGH",
            "uncertain": False,
            "explicit_overlap": False,
            "fallback_from_uncertain": True,
            "reason": "D26V3_PRACTICAL_SHAPE_FALLBACK",
        })
    return report


def _d26_finish_report(heat, obs, args, H=None) -> Dict[str, Any]:
    pass
    args = _d26_prepare_d25_args(args)
    
    
    
    args.d30_run_pose = False
    args.d31_lift_distance_mm = float(args.d32_lift_distance_mm)
    args.d31_lift_speed = float(args.d32_lift_speed)
    quality = d25v2.observation_quality_report(obs, args)
    shape = d25v2.d25_shape_report(obs, args, H)
    if heat is None or obs is None or getattr(obs, "mask", None) is None:
        wrinkle = {
            "good": False, "reason": "heatmap unavailable", "fold_count": 0,
            "heat_fold_count": 0, "outer_macro_fold_count": 0,
            "remaining": ["heatmap"],
        }
    else:
        wrinkle = d25v2._d25_fold_report_from_heat(obs, heat, H, args, shape)

    raw_leg_opening = _d26v2_leg_opening_guard(obs, args)
    leg_opening = _d27v3v2_effective_leg_report(raw_leg_opening, shape, quality, args)
    leg_opening["raw_report"] = copy.deepcopy(raw_leg_opening)
    residual = _d26v6_residual_wrinkle_guard(heat, obs, H, args)
    quality_good = bool(quality.get("good", False))
    base_shape_good = bool(shape.get("shape_good", False))
    leg_good = bool(leg_opening.get("good", False))
    explicit_overlap = bool(leg_opening.get("explicit_overlap", False))
    leg_tier = str(leg_opening.get("tier", "UNCERTAIN"))

    
    
    planner_shape_good = bool(base_shape_good and not explicit_overlap)
    shape["base_shape_good"] = base_shape_good
    shape["shape_good"] = planner_shape_good
    shape["finish_shape_good"] = bool(base_shape_good and leg_good)
    shape["leg_open_tier"] = leg_tier
    shape.setdefault("remaining", [])
    if explicit_overlap and "explicit_leg_overlap" not in shape["remaining"]:
        shape["remaining"].append("explicit_leg_overlap")

    wrinkle_good = bool(wrinkle.get("good", False))
    residual_good = bool(residual.get("good", False))
    good = bool(quality_good and base_shape_good and leg_good and wrinkle_good and residual_good)
    remaining: List[str] = []
    if not quality_good:
        remaining.append("observation")
    if not base_shape_good:
        remaining.extend([f"shape:{x}" for x in shape.get("remaining", ["failed"]) if x != "explicit_leg_overlap"])
    if leg_tier == "UNCERTAIN":
        remaining.append("legs:uncertain_rejudge")
    elif explicit_overlap:
        remaining.append("legs:explicit_overlap")
    elif not leg_good:
        remaining.append("legs:not_open")
    if not wrinkle_good:
        remaining.extend([f"fold:{x}" for x in wrinkle.get("remaining", ["failed"])])
    if not residual_good:
        remaining.append("surface:photo_supported_wrinkles_remain")

    summary = (
        f"{'FINISH' if good else 'REMAIN'} D27V3_V4 "
        f"quality={int(quality_good)} shape={float(shape.get('shape_score', 0.0)):.3f} "
        f"legs={leg_tier} macroFold={int(wrinkle.get('fold_count', 0))} "
        f"realResidual={int(residual.get('metrics', {}).get('significant_residual_count', 0))} "
        f"realAction={int(residual.get('metrics', {}).get('hard_action_candidate_count', 0))} "
        f"patternIgnored={int(residual.get('metrics', {}).get('ignored_pattern_count', 0))}"
    )
    report = {
        "good": good,
        "heat_good": bool(wrinkle_good and residual_good),
        "shape": shape,
        "quality": quality,
        "leg_opening": leg_opening,
        "wrinkle": wrinkle,
        "residual_wrinkle": residual,
        "checks": {
            "observation": quality_good,
            "base_shape": base_shape_good,
            "leg_open_for_finish": leg_good,
            "no_explicit_overlap": not explicit_overlap,
            "no_true_macro_fold": wrinkle_good,
            "no_photo_supported_surface_wrinkle": residual_good,
        },
        "limits": {
            "shape_score_min": float(getattr(args, "d25v2_shape_score_min", 0.52)),
            "macro_fold_max": int(getattr(args, "finish_max_t3_count", 0)),
        },
        "remaining": remaining,
        "summary": summary,
        "metrics": {
            "hard_action_candidate_count": int(residual.get("metrics", {}).get("hard_action_candidate_count", 0)),
            "significant_residual_count": int(residual.get("metrics", {}).get("significant_residual_count", 0)),
            "residual_total_area_ratio": float(residual.get("metrics", {}).get("residual_total_area_ratio", 0.0)),
            "ignored_pattern_count": int(residual.get("metrics", {}).get("ignored_pattern_count", 0)),
        },
    }
    shape["d26v2_leg_opening"] = leg_opening
    if heat is not None:
        heat.d26_finish_debug = report
    return report

def _d20_finish_report(heat, obs, args, H=None) -> Dict[str, Any]:
    pass
    return _d26_finish_report(heat, obs, args, H)


def _d21v4_good_enough_finish_report(heat, obs, H, args) -> Dict[str, Any]:
    pass
    report = _d26_finish_report(heat, obs, args, H)
    wr = report.get("wrinkle", {})
    sh = report.get("shape", {})
    return {
        "good": bool(report.get("good", False)),
        "enabled": True,
        "checks": report.get("checks", {}),
        "limits": report.get("limits", {}),
        "t3_count": int(wr.get("t3_count", 0)),
        "t2_count": int(wr.get("t2_count", 0)),
        "t1_allowed_count": int(wr.get("t1_allowed_count", 0)),
        "max_severity": 0.0,
        "actionable_ratio": float(wr.get("actionable_ratio", 0.0)),
        "max_blob_ratio": float(wr.get("max_blob_ratio", 0.0)),
        "shape_score": float(sh.get("shape_score", 0.0)),
        "symmetry_score": float(sh.get("pose_structure", {}).get("score", 0.0)),
        "remaining": list(report.get("remaining", [])),
        "summary": str(report.get("summary", "")),
        "d26_finish": report,
    }


def _d20_print_finish_banner(report: Dict[str, Any], required: int, cycle_count: int) -> None:
    print("\n" + "=" * 78)
    print("바지를 접는 판이 처리할 수 있는 형태로 만들었습니다.")
    consensus = report.get("consensus", {})
    print(
        f"카메라-clear {int(consensus.get('frame_count', 0))}프레임 중 "
        f"{int(consensus.get('required', required))}프레임 이상의 합의를 만족했습니다. "
        f"(자동 사이클 {cycle_count}회)"
    )
    print(f"최종 판정: {report.get('summary', '')}")
    print("한 프레임의 Pose·mask·무늬 반응만으로는 완료하지 않습니다.")
    print("=" * 78 + "\n")


def _d21v4_print_good_enough_banner(report: Dict[str, Any], required: int, cycle_count: int) -> None:
    finish = report.get("d26_finish", report)
    _d20_print_finish_banner(finish, required, cycle_count)


def _d26_press_candidate_plan(obs, heat, cand, ci, H, config, cfg, args):
    pass
    
    
    local_cand = copy.deepcopy(cand)
    geom = local_cand.setdefault("d21_geometry", {})
    if str(geom.get("shape_class", "IRREGULAR")) == "CURVE" and geom.get("arc_mid_board") is None:
        if geom.get("center_board") is not None:
            geom["arc_mid_board"] = np.asarray(geom["center_board"], dtype=np.float32)
    plan = _d22_make_press_sweep_plan(obs, heat, local_cand, ci, H, config, cfg, args)
    if plan is None or not plan.ok:
        return None
    plan.action = "D26_PRESS_SWEEP"
    plan.reason = "D26 closed-gripper press-only; " + str(plan.reason)
    plan.metrics.update({
        "policy_family": "D26_PRESS_ONLY",
        "d22_motion_mode": "PRESS_SWEEP",
        "d26_no_grip_open": True,
        "d26_press_gripper": float(getattr(args, "d26_press_gripper", 3.05)),
    })
    return plan


def build_d22_hybrid_wrinkle_plan(obs, heat, H, config, cfg, args):
    pass
    if heat is None or not heat.candidates:
        return None
    proposals: List[Tuple[float, DualWrinkleStretchPlan]] = []
    warnings: List[str] = []
    for ci, cand in enumerate(heat.candidates):
        plan = _d26_press_candidate_plan(obs, heat, cand, ci, H, config, cfg, args)
        if plan is None:
            warnings.append(f"W{ci+1}: outward press plan unavailable")
            continue
        score = (
            1_000_000.0 * int(cand.get("d20_priority_tier", 0))
            + 100_000.0 * float(cand.get("d21_severity", 0.0))
            + float(cand.get("priority_score", 0.0))
        )
        plan.metrics["d26_policy_score"] = float(score)
        plan.metrics["d26_original_shape_class"] = str(cand.get("d21_shape_class", "IRREGULAR"))
        plan.safety_warnings = list(warnings)
        proposals.append((score, plan))
    if not proposals:
        return None
    proposals.sort(key=lambda item: item[0], reverse=True)
    return proposals[0][1]


def _d17_build_pose_shape_plan(obs, H, config, cfg, args, shape_metrics):
    pass
    if obs is None or obs.pose is None or obs.mask is None:
        return None
    if bool(shape_metrics.get("shape_good", False)):
        return None
    reference = _d23v2_reference_center(obs)
    if reference is None:
        return None
    p = obs.pose
    candidates: List[Tuple[str, np.ndarray, float]] = []
    
    for name, point in (
        ("left_hem", p.left_hem_center),
        ("right_hem", p.right_hem_center),
        ("waist_left", p.waist_left),
        ("waist_right", p.waist_right),
    ):
        q = np.asarray(point, dtype=np.float32).reshape(2)
        radius = float(np.linalg.norm(q - reference))
        if np.isfinite(radius) and radius >= 10.0:
            candidates.append((name, q, radius))
    candidates.sort(key=lambda item: item[2])

    base_score = float(shape_metrics.get("shape_score", 0.0))
    severity = float(np.clip(0.82 - 0.55 * base_score, 0.38, 0.88))
    for name, problem, _radius in candidates:
        outward = _safe_unit(problem - reference)
        tangent = np.asarray([-outward[1], outward[0]], dtype=np.float32)
        px = board_to_pixel(H, float(problem[0]), float(problem[1]))
        if px is None:
            continue
        pseudo = {
            "center_px": [float(px[0]), float(px[1])],
            "major_axis_px": [1.0, 0.0],
            "major_length_mm": float(getattr(args, "d26_shape_press_max_mm", 85.0)),
            "area_px": 420.0,
            "d20_shadow_mean": 0.0,
            "d20_priority_tier": 2,
            "d21_severity": severity,
            "d21_geometry": {
                "shape_class": "IRREGULAR",
                "center_board": problem,
                "tangent_board": tangent,
                "normal_board": outward,
                "fit_confidence": 1.0,
            },
        }
        plan = _d26_press_candidate_plan(obs, None, pseudo, -1, H, config, cfg, args)
        if plan is None:
            continue
        plan.action = "D26_SHAPE_OUTWARD_PRESS"
        plan.reason = (
            f"D26 D25-v2 shape recovery: press {name} from center to outside; "
            f"shape_score={base_score:.3f}"
        )
        plan.metrics.update(dict(shape_metrics))
        plan.metrics.update({
            "policy_family": "D26_D25V2_SHAPE_PRESS",
            "d26_shape_target": name,
            "d26_no_grip_open": True,
        })
        return plan
    return None


