def setup_arms(args) -> Dict[str, RoArmSerial]:
    pass
    arms: Dict[str, RoArmSerial] = {}
    if not args.send:
        return arms
    arms["arm1"] = RoArmSerial(args.arm1_port, baudrate=115200, label="ARM1")
    arms["arm2"] = RoArmSerial(args.arm2_port, baudrate=115200, label="ARM2")
    open_angle = float(getattr(args, "d31_grip_open", getattr(args, "grip_open", 1.35)))
    try:
        
        arms["arm1"].set_gripper(
            open_angle, delay=0.25,
            stage="B31_STARTUP_OPEN", caller="setup_arms",
        )
        arms["arm2"].set_gripper(
            open_angle, delay=0.25,
            stage="B31_STARTUP_OPEN", caller="setup_arms",
        )
        time.sleep(0.05)
        print(f"[D32-B31-GRIPPER] startup OPEN={open_angle:.3f}rad on ARM1/ARM2")
    except Exception as exc:
        print(f"[D32-B31-GRIPPER] startup open failed: {exc!r}")
    return arms

def move_arm_to_standby(arm_key: str, arms: Dict[str, RoArmSerial], cfg: BottomSafetyConfig,
                        move_command: int = 104, reason: str = "standby") -> bool:
    pass
    arm = arms.get(arm_key)
    if arm is None:
        print(f"[D26-STANDBY] {arm_key.upper()} skipped: serial arm not connected")
        return False
    x, y, z, t = standby_roarm_pose(cfg, arm_key)
    print(
        f"[D26-STANDBY] {arm_key.upper()} {reason}: "
        f"roarm=({x:.1f},{y:.1f},{z:.1f}) t={t:.3f}; gripper unchanged"
    )
    arm.move_goal(x, y, z, t, cfg.speed, move_command=move_command)
    return True


def move_arms_to_standby(arms: Dict[str, RoArmSerial], cfg: BottomSafetyConfig,
                         move_command: int = 104, reason: str = "standby") -> bool:
    if not cfg.imaging_standby:
        print("[D26-STANDBY] skipped: imaging_standby=False")
        return False
    if cfg.dry_run or not cfg.send:
        print(f"[D26-STANDBY] dry-run/send guard: send={cfg.send} dry_run={cfg.dry_run}")
        return False
    ok = False
    
    
    for arm_key in ("arm2", "arm1"):
        try:
            ok = move_arm_to_standby(
                arm_key, arms, cfg, move_command=move_command, reason=reason
            ) or ok
            time.sleep(0.15)
        except Exception as exc:
            print(f"[D26-STANDBY] {arm_key.upper()} failed: {exc!r}")
    return ok


def _d26_execute_closed_press(plan, arms, cfg, move_command, args) -> bool:
    pass
    if len(plan.arm_points) != 1:
        print("[D26-EXEC] blocked: press-only action requires exactly one active arm")
        return False
    arm_key = next(iter(plan.arm_points.keys()))
    if arm_key not in arms:
        print(f"[D26-EXEC] missing serial arm: {arm_key}")
        return False
    p = plan.arm_points[arm_key]
    arm = arms[arm_key]
    angle = float(getattr(args, "d26_press_gripper", 3.05))
    speed = max(0.05, float(getattr(args, "d26_press_speed", 0.36)))
    down_extra = float(getattr(args, "d16_down_extra_wait_s", 0.30))
    sweep_extra = float(getattr(args, "d16_pull_extra_wait_s", 0.35))
    lift_extra = float(getattr(args, "d16_lift_extra_wait_s", 0.55))

    def move(key: str, label: str):
        xyz = p[key]
        print(f"[D26-{label}] {arm_key.upper()} ({xyz[0]:.1f},{xyz[1]:.1f},{xyz[2]:.1f})")
        arm.move_goal(
            float(xyz[0]), float(xyz[1]), float(xyz[2]),
            cfg.tool_t_rad, speed, move_command=move_command,
        )

    try:
        print(f"[D26-CLOSED-PRESS] {arm_key.upper()} angle={angle:.3f}; OPEN COMMAND DISABLED")
        arm.set_gripper(angle, delay=0.15)
        move("hover", "PRESS-HOVER")
        time.sleep(max(
            _d16_wait_seconds(p["lift"], p["hover"], speed, args, 0.0),
            float(getattr(args, "d23_high_z_wait_s", 0.55)),
        ))
        if cfg.hover_only:
            move("lift", "PRESS-END-HOVER")
            time.sleep(_d16_wait_seconds(p["hover"], p["lift"], speed, args, 0.0))
            return True
        move("down", "PRESS-DOWN")
        time.sleep(_d16_wait_seconds(p["hover"], p["down"], speed, args, down_extra))
        move("mid", "PRESS-MID")
        time.sleep(_d16_wait_seconds(p["down"], p["mid"], speed, args, sweep_extra))
        move("sweep", "PRESS-SWEEP")
        time.sleep(_d16_wait_seconds(p["mid"], p["sweep"], speed, args, sweep_extra))
        move("lift", "PRESS-LIFT")
        time.sleep(_d16_wait_seconds(p["sweep"], p["lift"], speed, args, lift_extra))
        print(f"[D26-CLOSED-PRESS] completed; {arm_key.upper()} gripper remains closed")
        return True
    except Exception as exc:
        print(f"[D26-PRESS-ERROR] {exc!r}")
        return False


def execute_dual_wrinkle_stretch_plan(plan: DualWrinkleStretchPlan,
                                      arms: Dict[str, RoArmSerial],
                                      cfg: BottomSafetyConfig,
                                      move_command: int = 104,
                                      args=None,
                                      skip_confirm: bool = False) -> bool:
    pass
    print_dual_wrinkle_plan(plan)
    if not plan.ok:
        print(f"[D26-EXEC] blocked: {plan.reason}")
        return False
    allowed = {"D26_PRESS_SWEEP", "D26_SHAPE_OUTWARD_PRESS"}
    if plan.action not in allowed:
        print(f"[D26-EXEC] blocked non-press action: {plan.action}")
        return False
    if len(plan.arm_points) != 1:
        print("[D26-EXEC] blocked: exactly one press arm is required")
        return False
    
    
    if not bool(plan.metrics.get("d23v2_center_outward_validation", {}).get("ok", True)):
        print("[D26-EXEC] blocked by stored center-outward validation")
        return False
    if cfg.dry_run or not cfg.send:
        print(f"[D26-EXEC] preview only: send={cfg.send} dry_run={cfg.dry_run}")
        return True
    if not skip_confirm and not confirm_if_needed(cfg, f"D26 {plan.action}"):
        print("[D26-EXEC] cancelled")
        return False
    ok = _d26_execute_closed_press(plan, arms, cfg, move_command, args)
    if ok and cfg.standby_after_motion:
        move_arms_to_standby(
            arms, cfg, move_command=move_command,
            reason=f"after D26 {plan.action}",
        )
    print(f"[D26-EXEC] completed action={plan.action} ok={ok}")
    return bool(ok)











STEP_D26_V3_BUILD = "2026-07-17-dual-aggressive-press-inset-roi-fast-return-v1"
_D26V3_RUNTIME_ARGS = None
_D26V3_BASE_BUILD_WRINKLE_HEATMAP = build_wrinkle_heatmap


def build_wrinkle_heatmap(frame: np.ndarray, mask_u8: Optional[np.ndarray], args) -> Optional[WrinkleHeatmapPlan]:
    pass
    if mask_u8 is None:
        return _D26V3_BASE_BUILD_WRINKLE_HEATMAP(frame, mask_u8, args)
    mask = ((np.asarray(mask_u8, np.uint8) > 0).astype(np.uint8) * 255)
    inset_px = max(0, int(getattr(args, "d26v3_boundary_inset_px", 28)))
    roi = mask
    used_px = 0
    if inset_px > 0 and cv2.countNonZero(mask) > 100:
        distance = cv2.distanceTransform((mask > 0).astype(np.uint8), cv2.DIST_L2, 5)
        candidate = np.zeros_like(mask)
        candidate[distance >= float(inset_px)] = 255
        original_area = float(max(1, cv2.countNonZero(mask)))
        ratio = float(cv2.countNonZero(candidate)) / original_area
        min_ratio = float(getattr(args, "d26v3_boundary_inset_min_area_ratio", 0.42))
        if ratio >= min_ratio and cv2.countNonZero(candidate) >= 300:
            roi = candidate
            used_px = inset_px
        else:
            
            for scale in (0.80, 0.65, 0.50, 0.35):
                trial_px = max(2, int(round(inset_px * scale)))
                candidate = np.zeros_like(mask)
                candidate[distance >= float(trial_px)] = 255
                ratio = float(cv2.countNonZero(candidate)) / original_area
                if ratio >= min_ratio and cv2.countNonZero(candidate) >= 300:
                    roi = candidate
                    used_px = trial_px
                    break

    local_args = copy.copy(args)
    
    
    local_args.wrinkle_heatmap_erode_px = 0
    plan = _D26V3_BASE_BUILD_WRINKLE_HEATMAP(frame, roi, local_args)
    if plan is not None:
        plan.d26v3_boundary_inset_px = int(used_px)
        plan.d26v3_full_mask_area_px = int(cv2.countNonZero(mask))
        plan.d26v3_inset_roi_area_px = int(cv2.countNonZero(roi))
        plan.summary = f"D26V3 insetROI={used_px}px; " + str(plan.summary)
    return plan


def _d26v3_arm_of_plan(plan: Optional[DualWrinkleStretchPlan]) -> Optional[str]:
    if plan is None or not plan.ok or len(plan.arm_points) != 1:
        return None
    key = next(iter(plan.arm_points.keys()))
    return key if key in ("arm1", "arm2") else None


def _d26v3_combine_press_plans(
    first: DualWrinkleStretchPlan,
    second: DualWrinkleStretchPlan,
    action: str,
    reason: str,
    args,
) -> Optional[DualWrinkleStretchPlan]:
    pass
    a1 = _d26v3_arm_of_plan(first)
    a2 = _d26v3_arm_of_plan(second)
    if a1 is None or a2 is None or a1 == a2:
        return None
    by_arm = {a1: first, a2: second}
    if set(by_arm) != {"arm1", "arm2"}:
        return None

    s1 = np.asarray(by_arm["arm1"].arm_points["arm1"]["source_board"], np.float32)
    s2 = np.asarray(by_arm["arm2"].arm_points["arm2"]["source_board"], np.float32)
    t1 = np.asarray(by_arm["arm1"].arm_points["arm1"]["target_board"], np.float32)
    t2 = np.asarray(by_arm["arm2"].arm_points["arm2"]["target_board"], np.float32)
    start_sep = float(np.linalg.norm(s1 - s2))
    target_sep = float(np.linalg.norm(t1 - t2))
    if start_sep < float(getattr(args, "d26v3_dual_min_start_separation_mm", 105.0)):
        return None
    if target_sep < float(getattr(args, "d26v3_dual_min_target_separation_mm", 145.0)):
        return None
    
    if target_sep + 2.0 < start_sep:
        return None

    centers = []
    for item in (first, second):
        if item.center_board is not None:
            centers.append(np.asarray(item.center_board, np.float32))
    center = np.mean(np.stack(centers), axis=0) if centers else 0.5 * (s1 + s2)
    metrics = {
        "policy_family": "D26V3_DUAL_CLOSED_PRESS",
        "d26v3_dual_press": True,
        "d26v3_start_separation_mm": start_sep,
        "d26v3_target_separation_mm": target_sep,
        "d26v3_parallel_outward_sweep": bool(getattr(args, "d26v3_parallel_outward_sweep", True)),
        "d26_no_grip_open": True,
        "active_arm": "both",
        "arm1_source_action": str(by_arm["arm1"].action),
        "arm2_source_action": str(by_arm["arm2"].action),
    }
    
    for arm_key, item in by_arm.items():
        metrics[f"{arm_key}_press_distance_mm"] = float(
            item.metrics.get("d22_press_distance_mm", np.linalg.norm(
                np.asarray(item.arm_points[arm_key]["target_board"], np.float32)
                - np.asarray(item.arm_points[arm_key]["source_board"], np.float32)
            ))
        )
        metrics[f"{arm_key}_candidate_index"] = int(item.candidate_index)
        metrics[f"{arm_key}_severity"] = float(item.metrics.get("d21_severity", 0.0))

    return DualWrinkleStretchPlan(
        True,
        reason,
        action=action,
        candidate_index=min(first.candidate_index, second.candidate_index),
        center_board=(float(center[0]), float(center[1])),
        arm_points={
            "arm2": copy.deepcopy(by_arm["arm2"].arm_points["arm2"]),
            "arm1": copy.deepcopy(by_arm["arm1"].arm_points["arm1"]),
        },
        metrics=metrics,
        safety_warnings=list(first.safety_warnings) + list(second.safety_warnings),
    )


def _d26v3_pose_press_for_arm(obs, heat, H, config, cfg, args, desired_arm: str, severity: Optional[float] = None):
    pass
    if obs is None or obs.pose is None or obs.mask is None:
        return None
    reference = _d23v2_reference_center(obs)
    if reference is None:
        return None
    p = obs.pose
    points = [
        ("left_hem", np.asarray(p.left_hem_center, np.float32)),
        ("right_hem", np.asarray(p.right_hem_center, np.float32)),
        ("waist_left", np.asarray(p.waist_left, np.float32)),
        ("waist_right", np.asarray(p.waist_right, np.float32)),
    ]
    
    
    ranked = []
    for name, q in points:
        if select_arm_for_board_x(cfg, float(q[0])) != desired_arm:
            continue
        radius = float(np.linalg.norm(q - reference))
        if radius >= 10.0:
            ranked.append((radius, name, q))
    ranked.sort(key=lambda item: item[0])
    sev = float(np.clip(
        getattr(args, "d26v3_assist_severity", 0.68) if severity is None else severity,
        0.35, 0.95,
    ))
    for _radius, name, q in ranked:
        outward = _safe_unit(q - reference)
        tangent = np.asarray([-outward[1], outward[0]], np.float32)
        px = board_to_pixel(H, float(q[0]), float(q[1]))
        if px is None:
            continue
        pseudo = {
            "center_px": [float(px[0]), float(px[1])],
            "major_axis_px": [1.0, 0.0],
            "major_length_mm": float(getattr(args, "d26v3_shape_press_max_mm", 125.0)),
            "area_px": 420.0,
            "priority_score": 1.0,
            "d20_shadow_mean": 0.0,
            "d20_priority_tier": 2,
            "d21_severity": sev,
            "d21_shape_class": "IRREGULAR",
            "d21_geometry": {
                "shape_class": "IRREGULAR",
                "center_board": q,
                "tangent_board": tangent,
                "normal_board": outward,
                "fit_confidence": 1.0,
            },
        }
        plan = _d26_press_candidate_plan(obs, heat, pseudo, -1, H, config, cfg, args)
        if plan is None or _d26v3_arm_of_plan(plan) != desired_arm:
            continue
        plan.action = "D26V3_ASSIST_OUTWARD_PRESS"
        plan.reason = f"D26_v3 opposite-side assist press at {name}"
        plan.metrics.update({
            "policy_family": "D26V3_ASSIST_PRESS",
            "d26v3_assist": True,
            "d26v3_assist_target": name,
        })
        return plan
    return None


def build_d22_hybrid_wrinkle_plan(obs, heat, H, config, cfg, args):
    pass
    if heat is None or not heat.candidates:
        return None
    proposals: List[Tuple[float, DualWrinkleStretchPlan]] = []
    for ci, cand in enumerate(heat.candidates):
        plan = _d26_press_candidate_plan(obs, heat, cand, ci, H, config, cfg, args)
        arm_key = _d26v3_arm_of_plan(plan)
        if plan is None or arm_key is None:
            continue
        score = (
            1_000_000.0 * int(cand.get("d20_priority_tier", 0))
            + 100_000.0 * float(cand.get("d21_severity", 0.0))
            + float(cand.get("priority_score", 0.0))
        )
        plan.metrics["d26_policy_score"] = float(score)
        plan.metrics["d26v3_candidate_arm"] = arm_key
        proposals.append((score, plan))
    if not proposals:
        return None
    proposals.sort(key=lambda item: item[0], reverse=True)
    best_by_arm = {}
    for score, plan in proposals:
        arm_key = _d26v3_arm_of_plan(plan)
        if arm_key not in best_by_arm:
            best_by_arm[arm_key] = (score, plan)

    if bool(getattr(args, "d26v3_prefer_dual_press", True)):
        if "arm1" in best_by_arm and "arm2" in best_by_arm:
            combined = _d26v3_combine_press_plans(
                best_by_arm["arm1"][1], best_by_arm["arm2"][1],
                "D26V3_DUAL_PRESS_SWEEP",
                "D26_v3 two wrinkle candidates -> paired outward closed press",
                args,
            )
            if combined is not None:
                return combined

        
        
        best_plan = proposals[0][1]
        active_arm = _d26v3_arm_of_plan(best_plan)
        missing = "arm1" if active_arm == "arm2" else "arm2"
        assist = _d26v3_pose_press_for_arm(obs, heat, H, config, cfg, args, missing)
        if assist is not None:
            combined = _d26v3_combine_press_plans(
                best_plan, assist,
                "D26V3_DUAL_PRESS_SWEEP",
                f"D26_v3 wrinkle press + {missing.upper()} outward assist",
                args,
            )
            if combined is not None:
                return combined
    return proposals[0][1]


def _d17_build_pose_shape_plan(obs, H, config, cfg, args, shape_metrics):
    pass
    if obs is None or obs.pose is None or obs.mask is None:
        return None
    if bool(shape_metrics.get("shape_good", False)):
        return None
    base_score = float(shape_metrics.get("shape_score", 0.0))
    severity = float(np.clip(0.92 - 0.55 * base_score, 0.56, 0.92))
    left = _d26v3_pose_press_for_arm(obs, None, H, config, cfg, args, "arm2", severity)
    right = _d26v3_pose_press_for_arm(obs, None, H, config, cfg, args, "arm1", severity)
    if left is not None and right is not None and bool(getattr(args, "d26v3_prefer_dual_press", True)):
        combined = _d26v3_combine_press_plans(
            left, right,
            "D26V3_DUAL_SHAPE_OUTWARD_PRESS",
            f"D26_v3 D25-v2 shape recovery with both arms; shape_score={base_score:.3f}",
            args,
        )
        if combined is not None:
            combined.metrics.update(dict(shape_metrics))
            combined.metrics["policy_family"] = "D26V3_DUAL_SHAPE_PRESS"
            return combined
    fallback = left if left is not None else right
    if fallback is not None:
        fallback.action = "D26_SHAPE_OUTWARD_PRESS"
        fallback.reason = f"D26_v3 one safe shape press only; shape_score={base_score:.3f}"
        fallback.metrics.update(dict(shape_metrics))
    return fallback


def _d26v3_stage_wait(a, b, speed: float, args, extra: float = 0.0, return_move: bool = False) -> float:
    wait = _d16_wait_seconds(a, b, speed, args, extra)
    if return_move:
        wait *= 0.58
    return max(0.18 if return_move else 0.28, float(wait))


def _d26v3_move_call(arm, xyz, cfg, speed, move_command):
    arm.move_goal(
        float(xyz[0]), float(xyz[1]), float(xyz[2]),
        cfg.tool_t_rad, float(speed), move_command=move_command,
    )


def _d26_execute_closed_press(plan, arms, cfg, move_command, args) -> bool:
    pass
    keys = [k for k in ("arm2", "arm1") if k in plan.arm_points]
    if len(keys) not in (1, 2):
        print("[D26-V3-EXEC] blocked: press plan requires one or two arms")
        return False
    if any(k not in arms for k in keys):
        print("[D26-V3-EXEC] missing serial arm")
        return False
    angle = float(getattr(args, "d26_press_gripper", 3.05))
    speed = max(0.05, float(getattr(args, "d26_press_speed", 0.36)))
    down_extra = float(getattr(args, "d16_down_extra_wait_s", 0.30))
    sweep_extra = float(getattr(args, "d16_pull_extra_wait_s", 0.35))
    lift_extra = float(getattr(args, "d16_lift_extra_wait_s", 0.55))

    def move(k, pose_key, label):
        xyz = plan.arm_points[k][pose_key]
        print(f"[D26-V3-{label}] {k.upper()} ({xyz[0]:.1f},{xyz[1]:.1f},{xyz[2]:.1f})")
        _d26v3_move_call(arms[k], xyz, cfg, speed, move_command)

    def parallel_move(pose_key, label):
        _run_parallel([
            (f"{k}-{pose_key}", lambda k=k: move(k, pose_key, label))
            for k in keys
        ])

    try:
        print(f"[D26-V3-CLOSED-PRESS] arms={keys} angle={angle:.3f}; OPEN COMMAND DISABLED")
        _run_parallel([
            (f"{k}-close", lambda k=k: arms[k].set_gripper(angle, delay=0.12))
            for k in keys
        ])
        
        if len(keys) == 2:
            parallel_move("hover", "PRESS-HOVER")
        else:
            move(keys[0], "hover", "PRESS-HOVER")
        time.sleep(max(float(getattr(args, "d23_high_z_wait_s", 0.55)), 0.35))

        if cfg.hover_only:
            if len(keys) == 2:
                parallel_move("lift", "PRESS-END-HOVER")
            else:
                move(keys[0], "lift", "PRESS-END-HOVER")
            time.sleep(0.45)
            return True

        
        for k in keys:
            p = plan.arm_points[k]
            move(k, "down", "PRESS-DOWN")
            time.sleep(_d26v3_stage_wait(p["hover"], p["down"], speed, args, down_extra))

        is_d47_dual = str(getattr(plan, "action", "")) == "D47_OCCUPANCY_PRESPREAD_DUAL"
        parallel_sweep = (
            len(keys) == 2
            and (
                is_d47_dual
                or bool(getattr(args, "d26v3_parallel_outward_sweep", True))
            )
        )
        if parallel_sweep:
            parallel_move("mid", "PRESS-MID")
            time.sleep(max(
                _d26v3_stage_wait(plan.arm_points[k]["down"], plan.arm_points[k]["mid"], speed, args, sweep_extra)
                for k in keys
            ))
            parallel_move("sweep", "PRESS-SWEEP")
            time.sleep(max(
                _d26v3_stage_wait(plan.arm_points[k]["mid"], plan.arm_points[k]["sweep"], speed, args, sweep_extra)
                for k in keys
            ))
            parallel_move("lift", "PRESS-LIFT")
            time.sleep(max(
                _d26v3_stage_wait(plan.arm_points[k]["sweep"], plan.arm_points[k]["lift"], speed, args, lift_extra, return_move=True)
                for k in keys
            ))
        else:
            
            for k in keys:
                p = plan.arm_points[k]
                move(k, "mid", "PRESS-MID")
                time.sleep(_d26v3_stage_wait(p["down"], p["mid"], speed, args, sweep_extra))
                move(k, "sweep", "PRESS-SWEEP")
                time.sleep(_d26v3_stage_wait(p["mid"], p["sweep"], speed, args, sweep_extra))
                move(k, "lift", "PRESS-LIFT")
                time.sleep(_d26v3_stage_wait(p["sweep"], p["lift"], speed, args, lift_extra, return_move=True))
        print(f"[D26-V3-CLOSED-PRESS] completed; grippers remain closed")
        return True
    except Exception as exc:
        print(f"[D26-V3-PRESS-ERROR] {exc!r}")
        return False


def execute_dual_wrinkle_stretch_plan(plan: DualWrinkleStretchPlan,
                                      arms: Dict[str, RoArmSerial],
                                      cfg: BottomSafetyConfig,
                                      move_command: int = 104,
                                      args=None,
                                      skip_confirm: bool = False) -> bool:
    print_dual_wrinkle_plan(plan)
    if not plan.ok:
        print(f"[D26-V3-EXEC] blocked: {plan.reason}")
        return False
    allowed = {
        "D26_PRESS_SWEEP", "D26_SHAPE_OUTWARD_PRESS",
        "D26V3_ASSIST_OUTWARD_PRESS", "D26V3_DUAL_PRESS_SWEEP",
        "D26V3_DUAL_SHAPE_OUTWARD_PRESS",
        "D47_GLOBAL_PRESPREAD_DUAL", "D47_GLOBAL_PRESPREAD_SINGLE",
        "D47_OCCUPANCY_PRESPREAD_DUAL", "D47_OCCUPANCY_PRESPREAD_SINGLE",
    }
    if plan.action not in allowed:
        print(f"[D26-V3-EXEC] blocked non-press action: {plan.action}")
        return False
    if str(plan.action).startswith("D47_") and len(plan.arm_points) != 2:
        print("[D47-DUAL-ONLY] blocked: wrinkle spreading requires both arms")
        return False
    if len(plan.arm_points) not in (1, 2):
        print("[D26-V3-EXEC] blocked: expected one or two press arms")
        return False
    stored = plan.metrics.get("d23v2_center_outward_validation", {})
    if stored and not bool(stored.get("ok", False)):
        print("[D26-V3-EXEC] blocked by stored center-outward validation")
        return False
    if cfg.dry_run or not cfg.send:
        print(f"[D26-V3-EXEC] preview only: send={cfg.send} dry_run={cfg.dry_run}")
        return True
    if not skip_confirm and not confirm_if_needed(cfg, f"D26_v5 {plan.action}"):
        print("[D26-V3-EXEC] cancelled")
        return False
    ok = _d26_execute_closed_press(plan, arms, cfg, move_command, args)
    if ok and cfg.standby_after_motion:
        move_arms_to_standby(arms, cfg, move_command=move_command, reason=f"after D26_v5 {plan.action}")
    print(f"[D26-V3-EXEC] completed action={plan.action} ok={ok}")
    return bool(ok)


def move_arm_to_standby(arm_key: str, arms: Dict[str, RoArmSerial], cfg: BottomSafetyConfig,
                        move_command: int = 104, reason: str = "standby") -> bool:
    pass
    arm = arms.get(arm_key)
    if arm is None:
        print(f"[D26-V3-STANDBY] {arm_key.upper()} skipped: serial arm not connected")
        return False
    x, y, z, t = standby_roarm_pose(cfg, arm_key)
    runtime = _D26V3_RUNTIME_ARGS
    speed = float(getattr(runtime, "d26v3_return_speed", 0.24)) if runtime is not None else max(0.20, cfg.speed)
    print(
        f"[D26-V3-STANDBY] {arm_key.upper()} {reason}: "
        f"roarm=({x:.1f},{y:.1f},{z:.1f}) speed={speed:.2f}; gripper unchanged"
    )
    arm.move_goal(x, y, z, t, speed, move_command=move_command)
    return True


def move_arms_to_standby(arms: Dict[str, RoArmSerial], cfg: BottomSafetyConfig,
                         move_command: int = 104, reason: str = "standby") -> bool:
    if not cfg.imaging_standby:
        print("[D26-V3-STANDBY] skipped: imaging_standby=False")
        return False
    if cfg.dry_run or not cfg.send:
        print(f"[D26-V3-STANDBY] dry-run/send guard: send={cfg.send} dry_run={cfg.dry_run}")
        return False
    runtime = _D26V3_RUNTIME_ARGS
    parallel = bool(getattr(runtime, "d26v3_parallel_return", True)) if runtime is not None else True
    gap = float(getattr(runtime, "d26v3_return_command_gap_s", 0.03)) if runtime is not None else 0.03
    keys = [k for k in ("arm2", "arm1") if k in arms]
    if parallel and len(keys) == 2:
        _run_parallel([
            (f"{k}-standby", lambda k=k: move_arm_to_standby(k, arms, cfg, move_command, reason))
            for k in keys
        ])
        time.sleep(max(0.0, gap))
        return True
    ok = False
    for k in keys:
        ok = move_arm_to_standby(k, arms, cfg, move_command, reason) or ok
        time.sleep(max(0.0, gap))
    return ok











