                                denom = max(1e-6, old_peak[k] - float(old_start[k][2]))
                                rise01 = float(np.clip((float(p[2]) - float(old_start[k][2])) / denom, 0.0, 1.0))
                                p[2] = float(target_start[k][2]) + rise01 * (target_peak_z[k] - float(target_start[k][2]))
                                new_pair[k] = p
